#include<iostream>

using namespace std;

struct Node
{
    int data;
    Node *next;
};

class Queue
{
private:
    Node *front;
    Node *rear;
public:

    Queue()
{
    front = rear = NULL;
}

bool isEmpty()
{
    if (front == NULL)
    {
        return true;
    }
    else
    {
        return false;
    }
}

void enqueue(int value)
{
    // Dynamic Reserve Capacity

    Node *temp = new Node();
    temp->data = value;
    temp->next = NULL;

    if (front == NULL)
    {
        front = rear = temp;
        front->next = NULL;
        return;
    }

    rear->next = temp;
    rear = temp;
    rear->next = NULL;
}

int dequeue()
{
    if (!isEmpty())
    {
        Node *temp = front;
        front = front->next;
        int data = temp->data;
        delete temp;
        return data;
     }
    else
    {
        cout << "Queue is empty" << endl;
        return -1;
    }
